#include <stdio.h>

// Stack implemented with a fixed-size array of integers
#define STACK_MAX 100

typedef struct {
    int data[STACK_MAX];
    int top; // index of the top element, -1 if empty
} Stack;

// Initialize the stack
void stack_init(Stack* s) {
    s->top = -1;
}

// Check if the stack is empty
int stack_empty(const Stack* s) {
    return s->top == -1;
}

// Check if the stack is full
int stack_full(const Stack* s) {
    return s->top == STACK_MAX - 1;
}

// Push an element onto the stack; returns 0 on success, -1 on error (full)
int stack_push(Stack* s, int value) {
    if (stack_full(s)) {
        return -1; // error: stack is full
    }
    s->data[++(s->top)] = value;
    return 0;
}

// Pop the top element from the stack; returns 0 on success, -1 on error (empty)
int stack_pop(Stack* s, int* out) {
    if (stack_empty(s)) {
        return -1; // error: stack is empty
    }
    *out = s->data[(s->top)--];
    return 0;
}

// Retrieve the top element without removing it; returns 0 on success, -1 on error (empty)
int stack_top(const Stack* s, int* out) {
    if (stack_empty(s)) {
        return -1; // error: stack is empty
    }
    *out = s->data[s->top];
    return 0;
}

// Example usage (optional):
// int main() {
//     Stack s; stack_init(&s);
//     stack_push(&s, 10);
//     int x;
//     if (stack_top(&s, &x) == 0) printf("top=%d\n", x);
//     stack_pop(&s, &x);
//     return 0;
// }

